ay:inline-flex;align-items:center;padding:16px 32px;background:rgba(255,255,255,.04);color:rgba(255,255,255,.8);font-family:'Inter',sans-serif;font-size:11px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;border-radius:6px;border:1px solid rgba(255,255,255,.18);text-decoration:none;backdrop-filter:blur(12px);transition:all .3s ease;} .h-gb:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.4);} .h-webinar-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(212,168,83,.08);border:1px solid rgba(212,168,83,.25);border-radius:999px;padding:6px 16px;font-family:'Inter',sans-serif;font-size:9px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:#d4a853;margin-bottom:16px;}

selector .ao-master-wrap {
