selector {
  position: relative;
  overflow: hidden;
  background-color: #F5F0E8 !important;
}

/* The Animated Aura */
selector .ao-aura-bg {
  position: absolute;
  inset: -10% -10%;
  z-index: 1;
  filter: blur(80px);
  pointer-events: none;
  opacity: 0.6;
}

selector .ao-aura-blob {
  position: absolute;
  border-radius: 50%;
  animation: auraMove 20s infinite alternate ease-in-out;
}

selector .ao-aura-1 {
  width: 80%;
  height: 80%;
  background: radial-gradient(circle, #f9d58b 0%, transparent 70%);
  top: 10%;
  left: 10%;
  animation-duration: 25s;
}

selector .ao-aura-2 {
  width: 60%;
  height: 60%;
  background: radial-gradient(circle, #ffffff 0%, transparent 60%);
  bottom: 10%;
  right: 10%;
  animation-duration: 18s;
  animation-delay: -5s;
}

@keyframes auraMove {
  0% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(5%, 5%) scale(1.1); }
  100% { transform: translate(-5%, -2%) scale(0.9); }
}

/* Pulsating Shamanic Source */
selector .ao-source-wrap {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 40px;
  z-index: 2;
}

selector .ao-source-icon {
  width: 110px;
  height: 110px;
  background-image: url(https://abhayoyun.org/wp-content/uploads/icon1.png);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  position: relative;
  z-index: 3;
  animation: sourcePulse 4s infinite ease-in-out;
  filter: brightness(0) saturate(100%) invert(69%) sepia(54%) saturate(550%) hue-rotate(4deg) brightness(94%);
}

selector .ao-source-glow {
  position: absolute;
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: #d4a853;
  filter: blur(40px);
  opacity: 0.4;
  animation: glowPulse 3s infinite ease-in-out;
}

selector .ao-source-glow-outer {
  position: absolute;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: #f9d58b;
  filter: blur(60px);
  opacity: 0.2;
  animation: glowPulse 5s infinite ease-in-out reverse;
}

@keyframes sourcePulse {
  0%, 100% { transform: scale(1) rotate(0deg); filter: brightness(0) saturate(100%) invert(69%) sepia(54%) saturate(550%) hue-rotate(4deg) brightness(94%); }
  50% { transform: scale(1.12) rotate(5deg); filter: brightness(0) saturate(100%) invert(69%) sepia(54%) saturate(550%) hue-rotate(4deg) brightness(130%); }
}

@keyframes glowPulse {
  0%, 100% { transform: scale(1); opacity: 0.2; }
  50% { transform: scale(1.5); opacity: 0.4; }
}

/* Floating Particles */
selector .ao-particles {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}

selector .ao-particle {
  position: absolute;
  width: 4px;
  height: 4px;
  background: #d4a853;
  border-radius: 50%;
  box-shadow: 0 0 10px #d4a853;
  opacity: 0.4;
  animation: particleFloat 10s infinite linear;
}

@keyframes particleFloat {
  0% { transform: translateY(100vh) scale(0); opacity: 0; }
  20% { opacity: 0.6; }
  80% { opacity: 0.6; }
  100% { transform: translateY(-100px) scale(1); opacity: 0; }
}

/* High-vibration Content */
selector .ao-aura-content {
  position: relative;
  z-index: 5;
  text-align: center;
}

selector .ao-shimmer-text {
  background: linear-gradient(90deg, #0d1117, #d4a853, #0d1117);
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer 5s linear infinite;
}

@keyframes shimmer {
  to { background-position: 200% center; }
}

@media (max-width: 767px) {
  selector .ao-source-icon { width: 70px; height: 70px; }
  selector .ao-source-glow { width: 90px; height: 90px; }
}

